let S, N, D, modulosArr, ptsArr;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(2, 2, 8);
	frameRate(60);
	describe("visualization modulo red=mod2, green=mod3, blue=mod5 of numbers x+y = y+x");

	S = max(width, height);
	N = random([10, 20, 30, 40, 50]);
	D = ~~(0.5*S/N)*2;
  noFill();
	stroke("silver");
  strokeWeight(D);
	noStroke();

	initArrs();

  loop();
}

function draw() {
	if (frameCount === 0 || frameCount % 1000 === 0) {
		background(2, 2, 8);
		initArrs();
	}
	translate(D/2, D/2);
	addPoint();
	if (false)
	for (let p of ptsArr) {
		fill(p.clr);
		beginShape();
		for (let v of p.verArr) vertex(p.x*D + v.x, p.y*D + v.y)
		endShape();
	}
}

function initArrs(c = 3, n = 7) {
	ptsArr = [];

	modulosArr = [];
	let numArr = [];
	for (let i = 2; i < n; i++) numArr.push(i);
	shuffle(numArr, true);
	for (let i = 0; i < min(c, n-2); i++) modulosArr.push(numArr.shift());
	modulosArr = modulosArr.sort((a, b) => a - b);
	console.log(modulosArr);
}

function addPoint() {
	const x = ~~random(width/D);
	const y = ~~random(height/D);
	const val = x + y;

	const isMod = [];
	for (let m of modulosArr) isMod.push(val % m === 0);
	const clr = color(isMod[0] ? 255 : 48, isMod[1] ? 255 : 48, isMod[2] ? 255 : 48);


	const verArr = [{x: -D/2, y: -D/2}, {x: D/2, y: -D/2}, {x: D/2, y: D/2}, {x: -D/2, y: D/2}];
	const n = noise(12+x, 23+y, frameCount * 0.124);
	verArr.splice((verArr.length*n), 1);
	ptsArr.push({x, y, clr, verArr});

	fill(clr);
	beginShape();
	for (let v of verArr) vertex(x*D + v.x, y*D + v.y)
	endShape();
}

function noisom(v1, v2) {
	if (v1>v2) [v1, v2] = [v2, v1];
	var n = noise(v1, v2, frameCount/123);
	return v1+n*(v2-v1);
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
